package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaHaDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma Bika Asbahna", "Ya Allah, da kai muke shiga safiya, kuma da kai muke shiga magariba; Da Kai muke raye, kuma da Kai muke mutuwa, kuma zuwa gare Ka ne tashin matattu yake.", "Da safe.", "Annabi ﷺ ya koyar da Sahabbai da cewa safe da yamma."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma Bika Amsayna", "Ya Allah, da kai muke shiga magariba, kuma da kai muke shiga safiya; GareKa muke rayuwa kuma da Kai muke mutuwa, kuma zuwa gare Ka makma take.", "Da yamma.", "Annabi ﷺ ya koyar da Sahabbai da cewa safe da yamma."),
        "dua_afiyah_morning" to DuaText("Tambayar Afiyah", "Ya Allah ina rokonka gafara da lafiya duniya da lahira.", "Annabi ﷺ bai bar wannan addu'ar ba, safe ko maraice.", "Ba wanda aka ba wa abin da ya fi alheri."),
        "dua_afini_fi_badani" to DuaText("Lafiyar Jiki, Ji da Gani", "Ya Allah ka karawa jikina lafiya. Ya Allah ka karawa malam lafiya. Ya Allah ka karawa ganina lafiya. Babu abin bautawa face Kai.", "Sau uku kowace safiya da yamma.", "Addu'a don lafiya da kuma kariya ga gabobin."),
        "dua_ya_hayyu_aslih" to DuaText("Gyara Dukkan Al'amurana", "Ya Rayayye, Ya Ubangiji, da rahamarKa nake neman taimako: Ka gyara min dukkan al'amura na, kada ka bar ni ga kaina ko da kiftawar ido.", "Annabi ﷺ ya shawarci Fatimah (RA) da ta fadi safe da yamma.", "Neman taimakon Allah akan kowane lamari."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Tasbihi na Juwayriyah (RA)", "Tsarki ya tabbata ga Allah, kuma gõdiya ta tabbata a gare Shi - gwargwadon halittarSa, gwargwadon abin da Yake so, gwargwadon nauyin Al'arshinSa da tawadan kalmominSa.", "Sau uku da safe - ya fi awoyi na zikiri nauyi.", "Fadin wadannan kalmomi guda hudu sau uku ya fi zikiri tun daga ketowar alfijir har zuwa tsakiyar safiya."),
        "dua_salawat" to DuaText("Durood-e-Ibrahim", "Ya Allah ka yi salati ga Muhammadu ﷺ da alayen Muhammad kamar yadda Ka yi salati ga Ibrahim (AS) da alayen Ibrahim; Kai Abin godiya ne, Mai girma. Ya Allah Ka yi salati ga Muhammadu ﷺ da alayen Muhammad kamar yadda Ka yi albarka ga Ibrahim (AS) da alayen Ibrahim; Kai Abin godiya ne, Mai girma.", "Salati ga Annabi ﷺ a cikin salati da kowane lokaci.", "Duk wanda yayi salati sau daya, Allah yayi masa rahama goma (Muslim 408)."),
        "dua_wudu_after" to DuaText("Bayan Alwala", "Ina shaidawa babu abin bautawa da gaskiya sai Allah shi kadai, ba shi da abokin tarayya, kuma Muhammadu ﷺ bawanSa ne kuma ManzonSa ne. Ya Allah ka sanya ni cikin masu tuba da masu tsarkake kansu.", "Bayan kammala alwala.", "Ana bude masa kofofin Aljannah guda takwas ya shiga da duk wanda ya so."),
        "dua_wudu_before" to DuaText("Kafin Alwala", "Da sunan Allah.", "Lokacin fara alwala.", "Babu (cikakkiyar alwala) ga wanda bai ambaci sunan Allah a kanta ba."),
        "dua_istiftah" to DuaText("Bude Addu'a (Sana)", "Tsarki ya tabbata a gareka, ya Allah, kuma godiya ta tabbata gareka. Albarkacin sunanka, ɗaukaka ta tabbata ga ɗaukakarka, kuma babu abin bautawa face kai.", "A farkon sallah, daidai bayan bude takbir.", "Budaddiyar Addu'ar Sallah."),
        "dua_ruku" to DuaText("In Ruku", "Tsarki ya tabbata ga Ubangijina, Mabuwayi.", "Akalla sau uku a ruku'u.", "Sunnah tasbihi na ruku."),
        "dua_sujood" to DuaText("In Sujood", "Tsarki ya tabbata ga Ubangijina, Mafi ɗaukaka.", "A kalla sau uku a cikin sujood.", "Bawa ne mafi kusanci ga Ubangijinsa alhali yana cikin sujada (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Tashi daga Ruku", "Allah yana jin wanda ya gode masa. Ya Ubangijinmu, Gõdiya ta tabbata a gare Ka.", "Yayin da yake tashi daga ruku, kuma a tsaye.", "Duk wanda ‘Rabbana wa lakal-hamd’ ya zo daidai da na mala’iku, an gafarta masa zunubansa da suka gabata."),
        "dua_between_sajdas" to DuaText("Tsakanin Sajda Biyu", "Ubangijina Ka gafarta mini. Ubangijina Ka gafarta mini.", "Alhali yana zaune a tsakanin sujuda biyu.", "Addu'ar Sunnah ta zama tsakanin sujjada."),
        "dua_before_salam_four" to DuaText("Gudu daga Abubuwa Hudu (Kafin Sallama)", "Ya Allah ina neman tsarinka daga azabar wuta, da azabar kabari, da fitintinu na rayuwa da mutuwa, da sharrin fitinar Al-Masihu (Dajjal).", "Bayan kammala tashahud da salawat, kafin sallama.", "Annabi ﷺ yayi umarni da neman tsari daga wadannan abubuwa guda hudu."),
        "dua_qunoot_witr" to DuaText("Qunoot in Witr", "Ya Allah Ka shiryar da ni cikin wadanda ka shiryar, Ka kyautata min cikin wadanda ka kyautatawa, Ka sanya ni cikin kulawarKa a cikin wadanda ka dauki nauyin kulawarKa, Ka sanya min albarka a cikin abin da ka bayar, kuma Ka kare ni daga sharrin abin da ka hukunta. Kun hukunta kuma bãbu mai yin hukunci a kanku, kuma wanda kuke jiɓinci, bã ya wulãkantacce. Albarka ta tabbata gare ka, Ya Ubangijinmu.", "A cikin sallar witri - Annabi ﷺ ya koyar da Hasan bn Ali (RA).", "Sunnah qunoot of witri. (A cikin Hanafiyya kuma, Allahumma inna nasta’inuka’ shi ma sananne ne)."),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Inna Nasta'inuka)", "Ya Allah muna neman taimakonka da gafararka, mun yi imani da kai, kuma a gare ka muke dogaro, muna yabo gareka ta hanya mafi kyau, muna gode maka kuma bama butulcewa, kuma muna barin wanda ya saba maka. Ya Allah kai kadai muke bautawa, gareka muke addu'a da sujada, gareka muke gaggawa da jihadi, muna fatan rahamarka, muna tsoron azabarka; Lalle ne azãbarKa zã ta sãmu ga kãfirai.", "A cikin witri - aikin Hanafiyya.", "An ruwaito daga Umar (RA) a cikin qunoot."),
        "dua_sleep_aslamtu" to DuaText("Kalmomin Karshe Kafin Barci", "Ya Allah na mika kaina gareka, kuma na jinginar da al'amarina gareka, kuma na mayar da bayana zuwa ga tsarinka, saboda begenka da tsoronka. Babu mafaka kuma babu mafaka daga gare ku sai zuwa gare ku. Na yi imani da littafinKa wanda Ka saukar, da Annabinka wanda Ka aiko.", "Bayan wudu, kwance a gefen dama - kalmomi na ƙarshe kafin barci.", "Idan ya rasu a wannan daren, ya mutu akan fitrah (musulunci)."),
        "dua_waking_night" to DuaText("Tashi Da Dare", "Babu abin bautawa da gaskiya sai Allah, Shi kadai, ba tare da abokin tarayya ba. Nasa ne mulki kuma gõdiya ta tabbata, kuma Shĩ, a kan kõme, Mai ĩkon yi ne. Dukkan godiya ta tabbata ga Allah, daukaka ta tabbata ga Allah, babu abin bautawa da gaskiya sai Allah, Allah shi ne mafi girma, kuma babu wani karfi da karfi sai wurin Allah. Ya Allah ka gafarta mini.", "Akan tashi a cikin dare.", "Ana amsa addu'arsa, idan ya yi alwala ya yi addu'a, sallarsa ta karva."),
        "dua_hamm_ibn_masud" to DuaText("Addu'ar bakin ciki (Ibn Mas'ud)", "Ya Allah ni bawanka ne dan bawanka dan baiwarka. Kwankwallona yana hannunka, umarninka a kaina ya cika, umarninka kuma a kaina gaskiya ne. Ina rokonka da kowane suna naka, wanda Ka sanyawa kanka sunanka da shi, ko ka saukar da shi a cikin littafinka, ko ka sanar da wani daga cikin halittunka, ko ka kiyaye kanka da sanin gaibu – cewa Ka sanya Al-Qur’ani ya zama maɓuɓɓugar zuciyata, hasken ƙirjina, kawar da baƙin cikina da tafiyar damuwata.", "A cikin baƙin ciki da damuwa - Allah yana maye gurbin baƙin ciki da farin ciki.", "Allah ya yaye masa damuwarsa da bacin rai, kuma ya ba shi farin ciki a wurinsa."),
        "dua_difficulty_sahl" to DuaText("Lokacin Wani Abu Yayi Wahala", "Ya Allah babu wani abu mai sauki sai abin da ka sawwake, kuma Ka sauwake mai wahala idan ka so.", "Lokacin da wani abu ya ji wuya.", "Sauƙi a cikin jarrabawa da ayyuka masu wahala."),
        "dua_musibah" to DuaText("Akan Bala'i (Istirja)", "Ga Allah muke kuma zuwa gare Shi za mu koma. Ya Allah ka saka mani cikin bala'i na, ka musanya mani da mafi alheri.", "A kan kowace asara ko bala'i.", "Lallai Allah yana ba da wani abu mafifici - Ummu Salamah (RA) an ba wa Annabi ﷺ."),
        "dua_debt" to DuaText("Domin Taimakon Bashi", "Ya Allah Ka wadatar da ni da abin da ka halatta a kan abin da ka haramta, kuma da falalarka ka sanya ni in bar wanin Kai.", "Domin biyan bashi - Ali (RA) ya koyar.", "Koda bashin kamar dutse ne Allah zai daidaita shi."),
        "dua_anger" to DuaText("Lokacin Fushi", "Ina neman tsarin Allah daga Shaidan La'ananne.", "Lokacin fushi.", "Annabi ﷺ ya ce: idan ya fadi haka, fushinsa zai tafi."),
        "dua_waswasa" to DuaText("Against Waswasa a Faith", "Na yi imani da Allah da manzanninsa.", "Lokacin da wasiƙar shaidan game da bangaskiya ta zo.", "Idan waswasi ta zo sai ka fadi wannan ka dakata (kuma ka nemi tsarin Allah)."),
        "dua_travel_full" to DuaText("Cikakken Addu'ar Balaguro", "Ya Allah muna rokonka akan wannan tafiya da kyautatawa da takawa, da ayyukan da zasu faranta maka. Ya Allah ka kawo mana saukin wannan tafiya, ka kuma takaita ta. Ya Allah Kai ne Abokin Tafiya kuma Majibincin Iyali.", "Lokacin tashi kan tafiya, bayan 'Subhanalladhi sakhkhara'.", "Cikakken addu'ar tafiya Sunnah."),
        "dua_return_travel" to DuaText("Ana dawowa daga Tafiya", "Muna komawa ne, muna tuba, muna bautawa Ubangijinmu da yabo.", "Akan dawowa daga tafiya.", "Annabi ﷺ ya fadi haka a kan dawowa daga tafiya."),
        "dua_farewell_traveller" to DuaText("Yin Ban-kwana ga Matafiyi", "Na baiwa Allah addininku da amanar ku da sakamakon ayyukanku.", "Lokacin bankwana da matafiyi.", "Abin da aka damka wa Allah ba ya taba bata."),
        "dua_entering_town" to DuaText("Tsayawa a Wuri", "Ina neman tsari da cikakkiyar kalmomin Allah daga sharrin dukkan abin da ya halitta.", "Lokacin tsayawa a wani wuri ko isa a sabon gari.", "Babu abin da zai cutar da shi har sai ya tashi daga nan."),
        "dua_boarding_ship" to DuaText("Shiga Jirgin Ruwa / Mota", "Bismin Allah tafiyarta take da matattararta. Lalle Ubangijĩna Mai gãfara ne, Mai jin ƙai.", "Lokacin shiga jirgi ko abin hawa - maganar Annabi Nuhu (AS).", "Ayar Qur'ani - Addu'ar akwatin Nuhu (AS)."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar with Hayyul-Qayyum", "Ina neman gafara daga Allah, waninSa, babu abin bautawa, Rayayye, Mai azurtawa, kuma ina tuba zuwa gare Shi.", "Domin tuba.", "Ana gafarta masa zunubansa ko da ya gudu daga fagen fama."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "Ubangijina Ka gafartawa Kayi rahama, Kai ne Mafificin masu rahama.", "Addu'ar Alqur'ani - don gafara da rahama.", "Ayar karshe ta Suratul Mu'uminun."),
        "dua_majlis_kaffarah" to DuaText("Kaffarat al-Majlis", "Tsarki ya tabbata a gareka, ya Allah, kuma godiya ta tabbata gareka. Ina shaidawa babu abin bautawa da gaskiya sai Kai. Ina neman gafararKa kuma ina tuba zuwa gare Ka.", "Lokacin tashi daga taro.", "Ya zama kaffara ga duk wani kuskure da aka yi a cikin taron."),
        "dua_jami_forgiveness" to DuaText("Cikakken Gafara", "Ya Allah Ka gafarta mini kurakuraina, da jahilcina, da wuce gona da iri a cikin lamurana, da duk abin da Ka fi ni sani.", "Cikakken Addu'ar Annabi ﷺ.", "Annabi ﷺ ya kasance yana yin wannan dua."),
        "dua_parents_nuh" to DuaText("Addu'ar Nuhu (AS) ga Iyaye", "Ya Ubangiji Ka gafarta mini, ya mahaifana, da wanda ya shige gidana yana mai imani, da dukkan muminai maza da muminai mata.", "Domin mahaifansa da muminai.", "Addu'ar Annabi Nuhu (AS)."),
        "dua_shukr_parents" to DuaText("Godiya ga Iyaye & Zuri'a Na Gaskiya", "Ubangijina Ka ba ni ikon gode wa ni’imarKa wadda Ka yi mini ni’ima da iyayena, da aikata ayyukan kwarai wadanda suke yardar da Ka, kuma Ka sanya zuriyata ta kwarai. Lalle ne nĩ, inã tũba zuwa gare Ka, kuma ina daga mãsu sallamãwa.", "Addu'ar Alqur'ani ta cika shekaru arba'in.", "Godiya, kyawawan ayyuka da adalcin 'ya'yan mutum - duk a cikin dua guda."),
        "dua_intimacy" to DuaText("Kafin Dangantakar Aure", "Da sunan Allah. Ya Allah Ka nisantar da Shaidan daga gare mu, kuma Ka nisantar da Shaidan daga abin da (Ya'ya) Ka ba mu.", "Kafin dangantakar aure.", "Idan an hukunta yaro, Shaidan ba zai taba cutar da shi ba."),
        "dua_ibrahim_children_protection" to DuaText("Kariyar Gida da Yara", "Ubangijina, ka tabbatar da wannan birni, ka nisantar da ni da 'ya'yana daga bautar gumaka.", "Addu'ar Annabi Ibrahim (AS) - Domin kare lafiyar garin da 'ya'yansa.", "Addu'a don tsayawa tsayin daka akan tauhidi."),
        "dua_drinking_milk" to DuaText("Lokacin Shan Madara", "Ya Allah ka yi mana albarka, ka kara mana shi.", "Lokacin shan madara.", "Madara ya ishi duka abinci da abin sha."),
        "dua_iftar_host" to DuaText("Lokacin Buda baki Da Wasu", "Allah ka sa masu azumi su buda baki tare da kai, salihai su ci abincinka, Mala’iku kuma su yi maka addu’a.", "Lokacin buda baki a gidan wani.", "Addu'ar Annabi ﷺ ga mai gida."),
    )
}
